<?php
namespace App\Http\Controllers; use App\Models\{Purchase,Sale}; use Illuminate\Http\Request;
class TransactionController extends Controller { public function index(Request $r){$type=$r->get('type','all');$sales=Sale::with('user')->when($type==='purchases',fn($q)=>$q->whereRaw('1=0'))->get()->map(fn($x)=>(object)['ref'=>'SALE-'.str_pad($x->sale_id,4,'0',STR_PAD_LEFT),'date'=>$x->sale_date,'type'=>'Sale','user'=>$x->user?->username,'amount'=>$x->total_amount]);$purchases=Purchase::with('user')->when($type==='sales',fn($q)=>$q->whereRaw('1=0'))->get()->map(fn($x)=>(object)['ref'=>'PUR-'.str_pad($x->purchase_id,4,'0',STR_PAD_LEFT),'date'=>$x->purchase_date,'type'=>'Purchase','user'=>$x->user?->username,'amount'=>$x->total_amount]);$transactions=$sales->concat($purchases)->sortByDesc('date')->values();return view('transactions.index',compact('transactions','type'));}}
